 ;==========================================================================
 ;
 ; Known problems:
 ;	Currently incompatible with BASIC XE due to it relying on $DE-DF not
 ;	being modified by FADD/FSUB.
 ;
 ;==========================================================================
 ; Math pack memory usage constraints
 ;                                                                            INBUFF          DEGFLG
 ;                                                                  NSIGN  DIGRT          ZTEMP3
 ;                                                                EEXP  FCHRFLG       ZTEMP4        FPTR2       FPSCR
 ;                                                              FRX   ESIGN CIX   ZTEMP1        FLPTR     PLYARG      FPSCR1
 ;              $D4     $D8     $DC     $E0     $E4     $E8     $EC     $F0     $F4     $F8     $FC     | $05E0 $05E6 $05EC
 ;              . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . | ..................
 ;              [-- FR0 --] [-- FRE --] [-- FR1 --] [-- FR2 --]               [-] [-] [-] [-]   [-] [-] |
 ; FADD/FSUB    M M M M M M M . . . !!! M M M M M M . . . . . . . . . ! ! . . . . . . M M M . ! . . . . |
 ; FMUL         M M M M M M M M M M M M M r r r r r M M M M M M M M M ! ! . . . . M M M . . . ! . . . . |
 ; FDIV         M M M M M M M M M M M M M r r r r r M M M M M M M M M ! ! . . . . M . M . . . ! . . . . |
 ; PLYEVL       M M M M M M M M M M M M M M M M M M M M M M M M M M M M ! . . . . M M M M M . ! M M M M | MMMMMM............
 ; EXP/EXP10    M M M M M M M M M M M M M M M M M M M M M M M M M M M M M M . . . M M M M M . ! M M M M | MMMMMM............
 ; LOG/LOG10    M M M M M M M M M M M M M M M M M M M M M M M M M M M M M M . . . M M M M M . ! M M M M | MMMMMMMMMMMM......
 ; REDRNG       M M M M M M M M M M M M M M M M M M M M M M M M M M M . . . . . . M . M . . . ! M M M M | MMMMMMMMMMMM......
 ;
 ; AFP          M M M M M M M . . . . . . . . . . . . . . . . . M M M M M M M . . . . . . . . ! . . . . |
 ; FASC         r r r r r r . . . . . . . . . . . . . . . . . . . M . . . . M M M . . M . . . ! . . . . |
 ; IPF          M M M M M M . . . . !!! . . . . . . . . . . . . . . . . . . . . . . . . M M . ! . . . . |
 ; FPI          M M M M M M . . . . . . !!!!!!!!!!! . . . . . . M . . . . . . . . M . M M M M ! . . . . |
 ;
 ; M = modified by original math pack
 ; r = read by original math pack
 ; ! = program known to rely on not being modified
 ;
 ; Notes:
 ; [1] BASIC XE relies on $DE/DF not being touched by FADD, or FOR/NEXT
 ;     breaks.
 ; [2] MAC/65 relies on $DE/DF not being touched by IPF.
 ; [3] DARG relies on FPI not touching FR1.
 ; [4] ACTris 1.2 relies on FASC not touching lower parts of FR2.
 ; [5] Atari BASIC SQR() uses ESIGN ($EF).
 ; [6] Atari BASIC SIN() uses FCHRFLG ($F0).
 ;

_fpcocnt = $00ec ;FP: temporary storage - polynomial coefficient counter
_fptemp0 = $00f8 ;FP: temporary storage - transcendental temporary (officially ZTEMP4+1)
_fptemp1 = $00f9 ;FP: temporary storage - transcendental temporary (officially ZTEMP3)



 ;==========================================================================
 ; AFP [D800]	Convert ASCII string at INBUFF[CIX] to FR0
 ;

_afp = afp
afp:
mp_afp_dotflag = fr2
mp_afp_xinvert = fr2+1
mp_afp_cix0 = fr2+2
mp_afp_sign = fr2+3
mp_afp_digit2 = fr2+4

 ;skip initial spaces
jsr		skpspc

 ;init FR0 and one extra mantissa byte
lda		#$7f
sta		fr0
sta		mp_afp_digit2

ldx		#fr0+1
jsr		zf1

 ;clear decimal flag
sta		mp_afp_dotflag
sta		mp_afp_sign

 ;check for sign
ldy		cix
lda		(inbuff),y
cmp		#'+'
beq		mp_afp_isplus
cmp		#'-'
bne		mp_afp_postsign
ror		mp_afp_sign
mp_afp_isplus:
iny
mp_afp_postsign:
sty		mp_afp_cix0

 ;skip leading zeroes
lda		#'0'
jsr		fp_skipchar

 ;check if next char is a dot, indicating mantissa <1
lda		(inbuff),y
cmp		#'.'
bne		mp_afp_not_tiny
iny

 ;set dot flag
ror		mp_afp_dotflag

 ;increment anchor so we don't count the dot as a digit for purposes
 ;of seeing if we got any digits
inc		mp_afp_cix0

 ;skip zeroes and adjust exponent
lda		#'0'
mp_afp_tiny_denorm_loop:
cmp		(inbuff),y
bne		mp_afp_tiny_denorm_loop_exit
dec		fr0
iny
bne		mp_afp_tiny_denorm_loop
mp_afp_tiny_denorm_loop_exit:

mp_afp_not_tiny:

 ;grab digits left of decimal point
ldx		#1
mp_afp_nextdigit:
lda		(inbuff),y
cmp		#'E'
beq		mp_afp_isexp
iny
cmp		#'.'
beq		mp_afp_isdot
eor		#'0'
cmp		#10
bcs		mp_afp_termcheck

 ;write digit if we haven't exceeded digit count
cpx		#6
bcs		mp_afp_afterwrite

bit		mp_afp_digit2
bpl		mp_afp_writehi

 ;clear second digit flag
dec		mp_afp_digit2

 ;merge in low digit
ora		fr0,x
sta		fr0,x

 ;advance to next byte
inx
bne		mp_afp_afterwrite

mp_afp_writehi:
 ;set second digit flag
inc		mp_afp_digit2

 ;shift digit to high nibble and write
asl
asl
asl
asl
sta		fr0,x

mp_afp_afterwrite:
 ;adjust digit exponent if we haven't seen a dot yet
bit		mp_afp_dotflag
bmi :+
inc	fr0
:

 ;go back for more
jmp		mp_afp_nextdigit

mp_afp_isdot:
lda		mp_afp_dotflag
bne		mp_afp_termcheck

 ;set the dot flag and loop back for more
ror		mp_afp_dotflag
bne		mp_afp_nextdigit

mp_afp_termcheck:
dey
cpy		mp_afp_cix0
beq		mp_afp_err_carryset
mp_afp_term:
 ;stash offset
sty		cix

mp_afp_term_rollback_exp:
 ;divide digit exponent by two and merge in sign
rol		mp_afp_sign
ror		fr0

 ;check if we need a one digit shift
bcs		mp_afp_nodigitshift

 ;shift right one digit
ldx		#4
mp_afp_digitshift:
lsr		fr0+1
ror		fr0+2
ror		fr0+3
ror		fr0+4
ror		fr0+5
dex
bne		mp_afp_digitshift

mp_afp_nodigitshift:
jmp		fp_normalize

mp_afp_err_carryset:
rts

mp_afp_isexp:
cpy		mp_afp_cix0
beq		mp_afp_err_carryset

 ;save off this point as a fallback in case we don't actually have
 ;exponential notation
sty		cix

 ;check for sign
ldx		#0
iny
lda		(inbuff),y
cmp		#'+'
beq		mp_afp_isexpplus
cmp		#'-'
bne		mp_afp_postexpsign
dex ;x=$ff
mp_afp_isexpplus:
iny
mp_afp_postexpsign:
stx		mp_afp_xinvert

 ;pull up to two exponent digits -- check first digit
jsr		fp_isdigit_y
iny
bcs		mp_afp_term_rollback_exp

 ;stash first digit
tax

 ;check for another digit
jsr		fp_isdigit_y
bcs		mp_afp_notexpzero2
iny

adc		fp_mul10,x
tax
mp_afp_notexpzero2:
txa

 ;zero is not a valid exponent
beq		mp_afp_term_rollback_exp

 ;check if mantissa is zero -- if so, don't bias
 ;	ldx		fr0+1
 ;	beq		term

 ;apply sign to exponent
eor		mp_afp_xinvert
rol		mp_afp_xinvert

 ;bias digit exponent
adc		fr0
sta		fr0
mp_afp_expterm:
jmp		mp_afp_term



 ;==========================================================================
fp_fmul_carryup:
mp_fp_fmul_carryup_round_loop:
adc		fr0,x
sta		fr0,x
mp_fp_fmul_carryup_dec_entry:
dex
lda		#0
bcs		mp_fp_fmul_carryup_round_loop
rts


 ;==========================================================================
fp_tab_lo_100:
.repeat 10, mp_index
.byte <(100*mp_index)
.endrepeat


 ;==========================================================================
.res $e6-(*-fb_math_base), $ea
_fasc = fasc
fasc:
mp_fasc_dotcntr = ztemp4
mp_fasc_expval = ztemp4+1
mp_fasc_trimbase = ztemp4+2
jsr		ldbufa
ldy		#0

 ;read exponent and check if number is zero
lda		fr0
bne		mp_fasc_notzero

lda		#$b0
sta		(inbuff),y
rts

mp_fasc_notzero:
sty		mp_fasc_expval
sty		mp_fasc_trimbase

 ;insert sixth mantissa byte
sty		fr0

 ;check if number is negative
bpl		mp_fasc_ispos
ldx		#'-'
dec		inbuff
stx		lbuff-1
inc		mp_fasc_trimbase
iny
mp_fasc_ispos:

 ;set up for 5 mantissa bytes
ldx		#-5

 ;compute digit offset to place dot
 ;  0.001 (10.0E-04) = 3E 10 00 00 00 00 -> -1
 ;   0.01 ( 1.0E-02) = 3F 01 00 00 00 00 -> 1
 ;    0.1 (10.0E-02) = 3F 10 00 00 00 00 -> 1
 ;    1.0 ( 1.0E+00) = 40 01 00 00 00 00 -> 3
 ;   10.0 (10.0E+00) = 40 10 00 00 00 00 -> 3
 ;  100.0 ( 1.0E+02) = 40 01 00 00 00 00 -> 5
 ; 1000.0 (10.0E+02) = 40 10 00 00 00 00 -> 5

asl
sec
sbc		#125

 ;check if we should go to exponential form (exp >= 10 or <=-3)
cmp		#12
bcc		mp_fasc_noexp

 ;yes - compute and stash explicit exponent
sbc		#2 ;!! - carry set from BCC fail
sta		mp_fasc_expval ;$0A <= expval < $FE

 ;reset dot counter
lda		#2

 ;exclude first two digits from zero trim
inc		mp_fasc_trimbase
inc		mp_fasc_trimbase

mp_fasc_noexp:
 ;check if number is less than 1.0 and init dot counter
cmp		#2
bcs		mp_fasc_not_tiny

 ;use sixth mantissa byte
adc		#2
dex
mp_fasc_not_tiny:
sta		mp_fasc_dotcntr ;$02 <= dotcntr < $0C

 ;check if number begins with a leading zero
lda		fr0+6,x
cmp		#$10
bcs		mp_fasc_digitloop

dec		mp_fasc_trimbase

 ;yes - skip the high digit
lsr		mp_fasc_expval
asl		mp_fasc_expval
bne		mp_fasc_writelow
dec		mp_fasc_dotcntr
bcc		mp_fasc_writelow

 ;write out mantissa digits
mp_fasc_digitloop:
dec		mp_fasc_dotcntr
bne		mp_fasc_no_hidot
lda		#'.'
sta		(inbuff),y
iny
mp_fasc_no_hidot:

 ;write out high digit
lda		fr0+6,x
lsr
lsr
lsr
lsr
ora		#$30
sta		(inbuff),y
iny

mp_fasc_writelow:
 ;write out low digit
dec		mp_fasc_dotcntr
bne		mp_fasc_no_lodot
lda		#'.'
sta		(inbuff),y
iny
mp_fasc_no_lodot:

lda		fr0+6,x
and		#$0f
ora		#$30
sta		(inbuff),y
iny

 ;next digit
inx
bne		mp_fasc_digitloop

 ;skip trim if dot hasn't been written
lda		mp_fasc_dotcntr
bpl		mp_fasc_skip_zero_trim

 ;trim off leading zeroes
lda		#'0'
mp_fasc_lzloop:
cpy		mp_fasc_trimbase
beq		mp_fasc_stop_zero_trim
dey
cmp		(inbuff),y
beq		mp_fasc_lzloop

 ;trim off dot
mp_fasc_stop_zero_trim:
lda		(inbuff),y
cmp		#'.'
bne		mp_fasc_no_trailing_dot

mp_fasc_skip_zero_trim:
dey
lda		(inbuff),y
mp_fasc_no_trailing_dot:

 ;check if we have an exponent to deal with
ldx		mp_fasc_expval
beq		mp_fasc_noexp2

 ;print an 'E'
lda		#'E'
iny
sta		(inbuff),y

 ;check for a negative exponent
txa
bpl		mp_fasc_exppos
eor		#$ff
tax
inx
lda		#'-'
.byte $2c
mp_fasc_exppos:
lda		#'+'
mp_fasc_expneg:
iny
sta		(inbuff),y

 ;print tens digit, if any
txa
sec
ldx		#$2f
mp_fasc_tensloop:
inx
sbc		#10
bcs		mp_fasc_tensloop
pha
txa
iny
sta		(inbuff),y
pla
adc		#$3a
iny
mp_fasc_noexp2:
 ;set high bit on last char
ora		#$80
sta		(inbuff),y
rts


 ;==========================================================================
 ; IPF [D9AA]	Convert 16-bit integer at FR0 to FP
 ;
 ; !NOTE! Cannot use FR2/FR3 -- MAC/65 requires that $DE-DF be preserved.
 ;
.res $1aa-(*-fb_math_base), $ea
ipf:
sed

ldx		#fr0+2
ldy		#5
jsr		zfl

ldy		#16
mp_ipf_byteloop:
 ;shift out binary bit
asl		fr0
rol		fr0+1

 ;shift in BCD bit
lda		fr0+4
adc		fr0+4
sta		fr0+4
lda		fr0+3
adc		fr0+3
sta		fr0+3
rol		fr0+2

dey
bne		mp_ipf_byteloop

lda		#$43
sta		fr0

jmp		fp_normalize_cld


 ;==========================================================================
 ; FPI [D9D2]	Convert FR0 to 16-bit integer at FR0 with rounding
 ;
 ; This cannot overwrite FR1. Darg relies on being able to stash a value
 ; there across a call to FPI in its startup.
 ;
.res $1d2-(*-fb_math_base), $ea
fpi:
mp_fpi__acc0 = fr2
mp_fpi__acc1 = fr2+1

 ;error out if it's guaranteed to be too big or negative (>999999)
lda		fr0
cmp		#$43
bcs		mp_fpi_err

 ;zero number if it's guaranteed to be too small (<0.01)
sbc		#$3f-1 ;!!- carry is clear
bcc		zfr0

tax

 ;clear temp accum and set up rounding
lda		#0
ldy		fr0+1,x
cpy		#$50
rol ;!! - clears carry too
sta		fr0
lda		#0

 ;check for [0.01, 1)
dex
bmi		mp_fpi_done

 ;convert ones/tens digit pair to binary (one result byte: 0-100)
lda		fr0+1,x
jsr		fp_dectobin
adc		fr0
adc		fp_dectobin_tab,y
clc
sta		fr0
lda		#0

 ;check if we're done
dex
bmi		mp_fpi_done

 ;convert hundreds/thousands digit pair to binary (two result bytes: 0-10000)
lda		fr0+1,x
jsr		fp_dectobin
lda		fr0
adc		fp_tab_lo_1000,y
sta		fr0
lda		fp_tab_hi_1000,y
adc		#0
pha
lda		fr0+1,x
and		#$0f
tay
lda		fr0
adc		fp_tab_lo_100,y
sta		fr0
pla
adc		fp_tab_hi_100,y

 ;check if we're done
dex
bmi		mp_fpi_done

 ;convert ten thousands digit pair to binary (two result bytes: 0-100000, overflow possible)
ldy		fr0+1,x
cpy		#$07
bcs		mp_fpi_err
tax
tya
asl
asl
asl
asl
adc		fr0
sta		fr0
txa
adc		fp_tab_hi_10000-1,y

mp_fpi_done:
 ;move result back to FR0, with rounding
sta		fr0+1
mp_fpi_err:
rts


