fb_constants_start: ;optimized by fp_fld1r_const_fmul

fpconst_ten:
.byte $40,$10,$00,$00,$00,$00

fpconst_ln10:
.byte $40,$02,$30,$25,$85,$09

.assert >fb_constants_start=>(* - 1), lderror, "Math constants page"
 ;==========================================================================
 ; FDIV [DB28]	Divide FR0 / FR1 -> FR0
 ;
 ; Compatibility:
 ;	- It is important that FDIV rounds if FADD/FMUL do. Otherwise, some
 ;	  forms of square root computation can have a slight error on integers,
 ;	  which breaks TICKTOCK.BAS.
 ;
.res $328-(*-fb_math_base), $ea
fdiv:
mp_fdiv__digit = _fr3+1
mp_fdiv__index = _fr3+2
 ;check if divisor is zero
lda		fr1
beq		mp_fdiv_err

 ;check if dividend is zero
lda		fr0
beq		mp_fdiv_ok

 ;compute new exponent
jsr		mp_fp_adjust_exponent_fdiv_entry

jsr		fp_fdiv_init

mp_fdiv_digitloop:
 ;just keep going if we're accurate
lda		fr0
ora		fr0+1
beq		mp_fdiv_nextdigit

 ;check if we should either divide or add based on current sign (stored in carry)
bcc		mp_fdiv_incloop

jsr		fp_fdiv_decloop
bcc		mp_fdiv_nextdigit

mp_fdiv_incloop:
 ;decrement quotient mantissa byte
lda		#0
sbc		mp_fdiv__digit
ldx		mp_fdiv__index
mp_fdiv_downloop:
adc		fr2+8,x
sta		fr2+8,x
lda		#$99
dex
bcc		mp_fdiv_downloop

 ;add mantissas
clc
.repeat 6, mp_index
lda		fr0+(5-mp_index)
adc		fr1+(5-mp_index)
sta		fr0+(5-mp_index)
.endrepeat

 ;keep going until we overflow
bcc		mp_fdiv_incloop

mp_fdiv_nextdigit:
 ;shift dividend (make sure to save carry state)
php
ldx		#4
mp_fdiv_bitloop:
asl		fr0+5
rol		fr0+4
rol		fr0+3
rol		fr0+2
rol		fr0+1
rol		fr0
dex
bne		mp_fdiv_bitloop
plp

 ;next digit
lda		mp_fdiv__digit
eor		#$09
sta		mp_fdiv__digit
beq		mp_fdiv_digitloop

 ;next quo byte
inc		mp_fdiv__index
bne		mp_fdiv_digitloop

 ;move back to fr0
jsr		fp_fdiv_complete
cld
mp_fdiv_ok:
clc
rts
mp_fdiv_err:
sec
rts


 ;==========================================================================
 ; SKPSPC [DBA1]	Increment CIX while INBUFF[CIX] is a space
.res $3a1-(*-fb_math_base), $ea
skpspc:
lda		#' '
ldy		cix
fp_skipchar:
skpspc_loop:
cmp		(inbuff),y
bne		skpspc_xit
iny
bne		skpspc_loop
skpspc_xit:
sty		cix
rts

 ;==========================================================================
 ; ISDIGT [DBAF]	Check if INBUFF[CIX] is a digit (UNDOCUMENTED)
.res $3af-(*-fb_math_base), $ea
isdigt = _isdigt
_isdigt:
ldy		cix
fp_isdigit_y:
lda		(inbuff),y
sec
sbc		#'0'
cmp		#10
rts


 ;==========================================================================
fp_fdiv_decloop:
mp_fp_fdiv_decloop_decloop:
 ;increment quotient mantissa byte
lda		mp_fdiv__digit
ldx		mp_fdiv__index
mp_fp_fdiv_decloop_uploop:
adc		fr2+8,x
sta		fr2+8,x
lda		#0
dex
bcs		mp_fp_fdiv_decloop_uploop

 ;subtract mantissas
sec
.repeat 5, mp_index
lda		fr0+(5-mp_index)
sbc		fr1+(5-mp_index)
sta		fr0+(5-mp_index)
.endrepeat
lda		fr0
sbc		#0
sta		fr0

 ;keep going until we underflow
bcs		mp_fp_fdiv_decloop_decloop
rts


 ;==========================================================================
fp_fdiv_complete:
ldx		#fr2
ldy		_fr3
lda		fr2+1
bne		mp_fp_fdiv_complete_no_normstep
inx
dey
mp_fp_fdiv_complete_no_normstep:
sty		0,x
jmp fb_fld0r_zp


 ;==========================================================================
 ; NORMALIZE [DC00]	Normalize FR0 (UNDOCUMENTED)
.res $3ff-(*-fb_math_base), $ea
fp_normalize_cld:
cld
.assert *-fb_math_base=$400, error, "Math entry offset"
fp_normalize:
normalize:
ldy		#5
mp_normalize_normloop:
lda		fr0
and		#$7f
beq		mp_normalize_underflow2

ldx		fr0+1
beq		mp_normalize_need_norm

 ;Okay, we're done normalizing... check if the exponent is in bounds.
 ;It needs to be within +/-48 to be valid. If the exponent is <-49,
 ;we set it to zero; otherwise, we mark overflow.

cmp		#64-49
bcc		mp_normalize_underflow
cmp		#64+49
rts

mp_normalize_need_norm:
dec		fr0
ldx		#-5
mp_normalize_normloop2:
lda fr0+7,x
sta fr0+6,x
inx
bne		mp_normalize_normloop2
stx		fr0+6
dey
bne		mp_normalize_normloop

 ;Hmm, we shifted out everything... must be zero; reset exponent. This
 ;is critical since Atari Basic depends on the exponent being zero for
 ;a zero result.
sty		fr0
sty		fr0+1
mp_normalize_xit:
clc
rts

mp_normalize_underflow2:
clc
mp_normalize_underflow:
jmp		zfr0



 ;==========================================================================
 ; HELPER ROUTINES
 ;==========================================================================

fp_fdiv_init:
sta		_fr3

ldx		#fr2+1
jsr		zf1
lda		#$50
sta		fr2+7 ;rounding byte
sta		fr2 ;sentinel byte to prevent carries into FR1

ldx		#0
stx		fr0
stx		fr1

 ;check if dividend begins with a leading zero digit -- if so, shift it left 4
 ;and begin with the tens digit
lda		fr1+1
cmp		#$10
bcs		mp_fp_fdiv_init_start_with_ones

ldy		#4
mp_fp_fdiv_init_bitloop:
asl		fr1+5
rol		fr1+4
rol		fr1+3
rol		fr1+2
rol		fr1+1
dey
bne		mp_fp_fdiv_init_bitloop

ldx		#$09

mp_fp_fdiv_init_start_with_ones:

stx		mp_fdiv__digit
sed

ldx		#0-7
stx		mp_fdiv__index
sec
rts


 ;--------------------------------------------------------------------------
fp_fsub_cont:
 ;check if we had a borrow
bcs		mp_fp_fsub_cont_sub_xit
bcc		mp_fp_fsub_cont_borrow_loop_start

 ;propagate borrow up
mp_fp_fsub_cont_borrow_loop:
lda		fr0+1,x
sbc		#0
sta		fr0+1,x
bcs		mp_fp_fsub_cont_sub_xit
mp_fp_fsub_cont_borrow_loop_start:
dex
bpl		mp_fp_fsub_cont_borrow_loop

ldx		#5
sec
mp_fp_fsub_cont_diff_borrow:
lda		#0
sbc		fr0,x
sta		fr0,x
dex
bne		mp_fp_fsub_cont_diff_borrow
lda		#$80
eor		fr0
sta		fr0
mp_fp_fsub_cont_sub_xit:

mp_fp_fsub_cont_norm_loop:
 ;Check if the exponent is in bounds.
 ;It needs to be within +/-48 to be valid. If the exponent is <-49,
 ;we set it to zero. Overflow isn't possible as this is the mantissa
 ;subtraction path.
lda		fr0
and		#$7f
cmp		#64-49
bcc		mp_fp_fsub_cont_underflow

ldx		fr0+1
beq		mp_fp_fsub_cont_need_norm

 ;check if we need to round, i.e.:
 ; 2.00000000
 ;-0.000000005
 ;load rounding byte offset
ldx		fr1
cpx		#4
bcs		mp_fp_fsub_cont_no_round
lda		fr1+2,x
cmp		#$50
bcs		mp_fp_fsub_cont_round_up
mp_fp_fsub_cont_no_round:

clc
cld
rts

mp_fp_fsub_cont_need_norm:
ldx		#-4
mp_fp_fsub_cont_scan_loop:
dec		fr0
ldy		fr0+6,x
bne		mp_fp_fsub_cont_found_pos
inx
bne		mp_fp_fsub_cont_scan_loop

 ;hmm... mantissa is all zero.
mp_fp_fsub_cont_underflow2:
clc
mp_fp_fsub_cont_underflow:
cld
jmp		zfr0

mp_fp_fsub_cont_found_pos:
 ;shift up mantissa
ldy		#0
mp_fp_fsub_cont_shift_loop:
lda fr0+6,x
sta [FB_MATH_POINTERS+3],y
iny
inx
bne		mp_fp_fsub_cont_shift_loop

 ;clear remaining mantissa bytes
mp_fp_fsub_cont_clear_loop:
stx		fr0+1,y
iny
cpy		#6
bne		mp_fp_fsub_cont_clear_loop

 ;check if we need to round


 ;if not, loop back to check the exponent and exit
 ;	bcc		norm_loop
beq		mp_fp_fsub_cont_norm_loop

mp_fp_fsub_cont_round_up:
 ;jump back into fadd code to carry up and exit
ldx		#5
jmp		mp_fsub_sum_carryloop


 ;--------------------------------------------------------------------------
fp_fmul_innerloop:
mp_fp_fmul_innerloop__offset = _fr3+5
mp_fp_fmul_innerloop__offset2 = fr2

jsr		zfl

 ;set up for 7 bits per digit pair (0-99 in 0-127)
ldy		#7

 ;set rounding byte, assuming renormalize needed (fr0+2 through fr0+6)
lda		#$50
sta		fr0+7

 ;begin outer loop -- this is where we process one _bit_ out of each
 ;multiplier byte in FR2's mantissa (note that this is inverted in that
 ;it is bytes-in-bits instead of bits-in-bytes)
mp_fp_fmul_innerloop_offloop:

 ;begin inner loop -- here we process the same bit in each multiplier
 ;byte, going from byte 5 down to byte 1
ldx		#5
mp_fp_fmul_innerloop_offloop2:
 ;shift an inverted bit out of fr1 mantissa
lsr		fr2,x
bcs		mp_fp_fmul_innerloop_noadd

 ;add fr1 to fr0 at offset	
.repeat 6, mp_index
lda		fr0+(5-mp_index),x
adc		fr1+(5-mp_index)
sta		fr0+(5-mp_index),x
.endrepeat

 ;check if we have a carry out to the upper bytes
bcc		mp_fp_fmul_innerloop_no_carry
stx		mp_fp_fmul_innerloop__offset2
jsr		mp_fp_fmul_carryup_dec_entry
ldx		mp_fp_fmul_innerloop__offset2
mp_fp_fmul_innerloop_no_carry:

mp_fp_fmul_innerloop_noadd:
 ;go back for next byte
dex
bne		mp_fp_fmul_innerloop_offloop2

 ;double fr1
clc
lda		fr1+5
adc		fr1+5
sta		fr1+5
lda		fr1+4
adc		fr1+4
sta		fr1+4
lda		fr1+3
adc		fr1+3
sta		fr1+3
lda		fr1+2
adc		fr1+2
sta		fr1+2
lda		fr1+1
adc		fr1+1
sta		fr1+1
lda		fr1+0
adc		fr1+0
sta		fr1+0

 ;loop back until all mantissa bytes finished
dey
bne		mp_fp_fmul_innerloop_offloop

 ;check if no renormalize is needed, and if so, re-add new rounding
lda		fr0+1
beq		mp_fp_fmul_innerloop_renorm_needed

lda		#$50
ldx		#6
jsr		fp_fmul_carryup

mp_fp_fmul_innerloop_renorm_needed:
 ;all done
jmp		fp_normalize_cld


 ;==========================================================================
 ; PLYEVL [DD40]	Eval polynomial at (X:Y) with A coefficients using FR0
 ;
.res $53e-(*-fb_math_base), $ea
fp_plyevl_10:
lda		#10
plyevl:
 ;stash arguments
stx		fptr2
sty		fptr2+1
sta		_fpcocnt

 ;copy FR0 -> PLYARG
ldx		#<plyarg
ldy		#>plyarg
jsr		fst0r

jsr		zfr0

mp_plyevl_loop:
 ;load next coefficient and increment coptr
lda		fptr2
tax
clc
adc		#6
sta		fptr2
ldy		fptr2+1
bcc :+
inc	fptr2+1
:
jsr		fld1r

 ;add coefficient to acc
jsr		fadd
bcs		mp_plyevl_xit

dec		_fpcocnt
beq		mp_plyevl_xit

 ;copy PLYARG -> FR1
 ;multiply accumulator by Z and continue
ldx		#<plyarg
ldy		#>plyarg
jsr		fp_fld1r_fmul
bcc		mp_plyevl_loop
mp_plyevl_xit:
rts


