 ;==========================================================================
 ; EXP [DDC0]	Compute e^x
 ; EXP10 [DDCC]	Compute 10^x
 ;
.res $5c0-(*-fb_math_base), $ea
exp10 = mp_exp__exp10
exp:
ldx		#<fpconst_log10_e
ldy		#>fpconst_log10_e
jsr		fld1r ;we could use fp_fld1r_fmul, but then we have a hole :(
jsr		fmul
bcs		mp_exp_err2

.assert *-fb_math_base=$5cc, error, "Math entry offset"
mp_exp__exp10:
 ;stash sign and compute abs
lda		fr0
sta		_fptemp1
and		#$7f
sta		fr0

ldy		#0

 ;check for |exp| >= 100 which would guarantee over/underflow
cmp		#$40
bcc		mp_exp_abs_ok
beq		mp_exp_abs_large

mp_exp_abs_too_big:
 ;okay, the |x| is too big... check if the original was negative.
 ;if so, zero and exit, otherwise error.
lda		_fptemp1
bpl		mp_exp_err2
clc
jmp		zfr0

mp_exp_abs_large:
 ;|exp|>=1, so split it into integer/fraction
lda		fr0+1
jsr		fp_dectobin
adc		fp_dectobin_tab,y
pha
lda		#0
sta		fr0+1
sta		fr0+6
jsr		fp_normalize
pla
tay

mp_exp_abs_ok:
 ;stash integer portion of exponent
sty		_fptemp0

 ;compute approximation z = 10^y
ldx		#<mp_exp_coeff
ldy		#>mp_exp_coeff
jsr		fp_plyevl_10

 ;tweak exponent
lsr		_fptemp0

 ;scale by 10 if necessary
bcc		mp_exp_even
ldx		#<fpconst_ten
jsr		fp_fld1r_const_fmul
bcs		mp_exp_abs_too_big
mp_exp_even:

 ;bias exponent
lda		_fptemp0
adc		fr0
cmp		#64+49
bcs		mp_exp_abs_too_big
sta		fr0

 ;check if we should invert
rol		_fptemp1
bcc		mp_exp_xit2

jsr		fmove
ldx		#<fp_one
ldy		#>fp_one
jsr		fld0r
jmp		fdiv

mp_exp_err2:
mp_exp_xit2:
rts

mp_exp_coeff: ;Minimax polynomial for 10^x over 0 <= x < 1
.byte $3f,$01,$46,$90,$83,$08
.byte $be,$20,$05,$33,$11,$71
.byte $3f,$09,$19,$45,$20,$45
.byte $3f,$19,$21,$38,$38,$84
.byte $3f,$54,$47,$32,$51,$97
.byte $40,$01,$17,$01,$82,$50
.byte $40,$02,$03,$47,$85,$81
.byte $40,$02,$65,$09,$44,$94
.byte $40,$02,$30,$25,$85,$12
.byte $40,$01,$00,$00,$00,$00


 ;==========================================================================
fpconst_log10_e:
.byte $3f,$43,$42,$94,$48,$19

fp_carry_expup:
 ;adjust exponent
inc		fr0

 ;shift down FR0
ldx		#4
mp_fp_carry_expup_sum_shiftloop:
lda		fr0,x
sta		fr0+1,x
dex
bne		mp_fp_carry_expup_sum_shiftloop

 ;add a $01 at the top
inx
stx		fr0+1
rts


 ;==========================================================================
fp_fmul_fr0_to_binfr2: ;$15 bytes
ldx		#4
mp_fp_fmul_fr0_to_binfr2_loop:
lda		fr0+1,x
lsr
lsr
lsr
lsr
tay
clc
lda		fr0+1,x
adc		fp_dectobin_tab,y
eor		#$ff
sta		fr2+1,x
dex
bpl		mp_fp_fmul_fr0_to_binfr2_loop
fp_rts1:
rts


 ;==========================================================================
 ; REDRNG [DE95]	Reduce range via y = (x-C)/(x+C) (undocumented)
 ;
 ; X:Y = pointer to C argument
 ;
.res $695-(*-fb_math_base), $ea
redrng = _redrng
_redrng:
stx		fptr2
sty		fptr2+1
jsr		fld1r
ldx		#<fpscr
ldy		#>fpscr
jsr		fst0r
jsr		fadd
bcs		mp__redrng_fail
ldx		#<plyarg
ldy		#>plyarg
jsr		fst0r
ldx		#<fpscr
ldy		#>fpscr
jsr		fld0r
ldx		fptr2
ldy		fptr2+1
jsr		fld1r
jsr		fsub
bcs		mp__redrng_fail
ldx		#<plyarg
ldy		#>plyarg
jsr		fld1r
jmp		fdiv

mp__redrng_fail = fp_rts1


 ;==========================================================================
 ; LOG [DECD]	Compute ln x
 ; LOG10 [DED1]	Compute log10 x
 ;
.res $6cd-(*-fb_math_base), $ea
log10 = mp_log__log10
log:
lsr		_fptemp1
bpl		mp_log_entry
.assert *-fb_math_base=$6d1, error, "Math entry offset"
mp_log__log10:
sec
ror		_fptemp1
mp_log_entry:
 ;throw error on negative number
lda		fr0
bmi		mp_log_err

 ;stash exponentx2 - 128
asl
eor		#$80
sta		_fptemp0

 ;raise error if argument is zero
lda		fr0+1
beq		mp_log_err

 ;reset exponent so we are in 1 <= z < 100
ldx		#$40
stx		fr0

 ;split into three ranges based on mantissa:
 ;  1/sqrt(10) <= x < 1:            [31, 99] divide by 100
 ;  sqrt(10)/100 <= x < 1/sqrt(10): [ 3, 30] divide by 10
 ;  0 < x < sqrt(10)/100:           [ 1,  2] leave as-is

cmp		#$03
bcc		mp_log_post_range_adjust
cmp		#$31
bcc		mp_log_mid_range

 ;increase result by 1 (equivalent to *10 input)
inc		_fptemp0
bne		mp_log_adjust_exponent

mp_log_mid_range:
 ;multiply by 10
ldx		#<fpconst_ten
jsr		fp_fld1r_const_fmul
bcs		mp_log_err2

mp_log_adjust_exponent:
 ;increase result by 1 (equivalent to *10 input)
inc		_fptemp0

 ;divide fraction by 100
dec		fr0

mp_log_post_range_adjust:
 ;at this point, we have 0.30 <= z <= 3; apply y = (z-1)/(z+1) transform
 ;so we can use a faster converging series... this reduces y to
 ;0 <= y < 0.81
ldx		#<fp_one
ldy		#>fp_one
jsr		redrng

 ;stash y so we can later multiply it back in
ldx		#<fpscr
ldy		#>fpscr
jsr		fst0r

 ;square the value so we compute a series on y^2n
jsr		fmove
jsr		fmul

 ;do polynomial expansion
ldx		#<fpconst_log10coeff
ldy		#>fpconst_log10coeff
jsr		fp_plyevl_10
bcs		mp_log_err2

 ;multiply back in so we have series on y^(2n+1)
ldx		#<fpscr
ldy		#>fpscr
jsr		fp_fld1r_fmul

 ;stash
jsr		fmove

 ;convert exponent adjustment back to float (signed)
lda		#0
sta		fr0+1
ldx		_fptemp0
bpl		mp_log_expadj_positive
sec
sbc		_fptemp0
tax
mp_log_expadj_positive:
stx		fr0
jsr		ipf

 ;merge (cannot fail)
asl		fr0
asl		_fptemp0
ror		fr0
jsr		fadd

 ;scale if doing log
bit		_fptemp1
bmi		mp_log_xit2

