 ;==========================================================================
 ; HALF (used by Atari BASIC)
 ;
.res $76c-(*-fb_math_base), $ea
fpconst_half:
.byte $3f,$50,$00,$00,$00,$00

 ;==========================================================================
 ; log10(x) coefficients
 ;
 ; LOG10 computes:
 ;							-0.30 <= z <= 3.0
 ;	y = (z-1)/(z+1)			-0.54 <= y <= 0.5
 ;	x = y^2					0 <= x <= 0.29
 ;	log10(z) = f(x)*y
 ;
 ; Therefore:
 ;	f(x) = log10((1+y)/(1-y))/y
 ;
fpconst_log10coeff: ;Maclaurin series expansion for log10((z-1)/(z+1))
.byte $3f,$20,$26,$22,$71,$54
.byte $bf,$07,$32,$04,$49,$21
.byte $3f,$10,$60,$98,$35,$64
.byte $3f,$05,$60,$41,$73,$29
.byte $3f,$08,$04,$18,$84,$07
.byte $3f,$09,$63,$91,$60,$15
.byte $3f,$12,$40,$89,$61,$35
.byte $3f,$17,$37,$17,$66,$46
.byte $3f,$28,$95,$29,$65,$58
.byte $3f,$86,$85,$88,$96,$38

 ;==========================================================================
 ; Arctangent coefficients
 ;
 ; The 11 coefficients here form a power series approximation
 ; f(x^2) ~= atn(x)/x. This is not an official feature of the math pack but
 ; is relied upon by BASIC.
 ;
 ; We used to use the coefficients from Abramowitz & Stegun 4.4.49 here, but
 ; there seems to be an error there such that the result falls far short
 ; of the specified 2x10^-8 accuracy over 0<=x<=1 at x=1. Instead, we now
 ; use a custom minimax polynomial for f(y)=atn(sqrt(y))/sqrt(y) where y=x^2.
 ;
.res $7ae-(*-fb_math_base), $ea
atncoef: ;coefficients for atn(x)/x ~= f(x^2)
 ;see Abramowitz & Stegun 4.4.49

.byte $3e,$11,$12,$07,$58,$81 ;x**10*1.11207588057982e-3
.byte $be,$73,$04,$08,$75,$20 ;x**9*-7.30408751951452e-3
.byte $3f,$02,$24,$96,$55,$73 ;x**8*2.24965572957342e-2
.byte $bf,$04,$46,$18,$51,$72 ;x**7*-4.46185172165888e-2
.byte $3f,$06,$73,$46,$32,$45 ;x**6*6.73463245104305e-2
.byte $bf,$08,$80,$69,$06,$64 ;x**5*-8.80690663570546e-2
.byte $3f,$11,$05,$66,$74,$99 ;x**4*1.10566749879313e-1
.byte $bf,$14,$27,$94,$93,$12 ;x**3*-1.42794931245212e-1
.byte $3f,$19,$99,$96,$30,$60 ;x**2*1.99996306023439e-1
.byte $bf,$33,$33,$33,$24,$72 ;x**1*-3.33333247188074e-1
 ;x**0*9.99999999667198e-1
fp_one:
.byte $40,$01,$00,$00,$00,$00 ;also an arctan coeff
.res $7f0-(*-fb_math_base), $ea
fp_pi4: ;pi/4 - needed by Atari Basic ATN()
.byte $3f,$78,$53,$98,$16,$34

fp_dectobin_tab:
.repeat 10, mp_index
.byte <(-6*mp_index)
.endrepeat

